<?php $q=new WP_Query(['post_type'=>'event','posts_per_page'=>(int)($attributes['count']??6),'meta_key'=>'sb_event_date','orderby'=>'meta_value','order'=>'ASC','meta_query'=>[['key'=>'sb_event_date','value'=>current_time('Y-m-d'),'compare'=>'>=','type'=>'DATE']]]); ?><section class="sb-section alignfull"><div class="sb-container"><h2><?php echo esc_html($attributes['heading']??'Upcoming events'); ?></h2><div class="sb-card-grid"><?php while($q->have_posts()):$q->the_post();?><article class="sb-card"><p class="sb-eyebrow"><?php echo esc_html(get_post_meta(get_the_ID(),'sb_event_date',true)); ?></p><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(get_the_excerpt()); ?></p><a class="sb-text-link" href="<?php the_permalink(); ?>">Event details →</a></article><?php endwhile;wp_reset_postdata();?></div></div></section>
